{
  "responses": [
    {
      "tone": "positivo",
      "text": "Com certeza! Adoraria participar. Revisar os exercícios juntos vai ser super produtivo para a prova.",
      "probability": 0.35
    },
    {
      "tone": "informal",
      "text": "Fechado! Quarta está ótimo. Vamos deixar tudo bem tranquilo e focado na revisão.",
      "probability": 0.28
    },
    {
      "tone": "objetivo",
      "text": "Aceito o convite. Quarta-feira funciona perfeitamente para a revisão dos exercícios.",
      "probability": 0.25
    },
    {
      "tone": "cordial",
      "text": "Que ótima ideia! Estou totalmente a favor de revisarmos o material juntos na quarta-feira.",
      "probability": 0.20
    },
    {
      "tone": "entusiasmado",
      "text": "Sim, topo demais! Quarta-feira é perfeito para turbinar a revisão e gabaritar essa prova!",
      "probability": 0.15
    }
  ]
}
```

